class Solution {
    public int isPrefixOfWord(String sentence,String searchWord){
        String[] words=sentence.split(" ");
        for(int i=0;i<words.length;i++)if(words[i].startsWith(searchWord))return i+1;
        return -1;
    }
}

code.kotlin:
class Solution {
    fun isPrefixOfWord(sentence:String,searchWord:String):Int{
        for((index,word)in sentence.split(' ').withIndex())if(word.startsWith(searchWord))return index+1;
        return -1
    }
}

code.cpp:
class Solution {
    public: int isPrefixOfWord(string sentence,string searchWord){
        stringstream stream(sentence);
        string word;
        int index=1;
        while(stream>>word){
            if(word.rfind(searchWord,0)==0)return index;
            ++index;
        }
        return -1;
    }
};
